class Handler(http.server.SimpleHTTPRequestHandler):
    def get_role(self):
        cookie = self.headers.get('Cookie', '')
        cfg = load_config()
        if f'auth={ADMIN_PASS}' in cookie: return 'admin'
        if f'auth={cfg["guest_pass"]}' in cookie: return 'guest'
        return None

    def do_GET(self):
        global tunnel_url
        role = self.get_role()
        if self.path == '/' or self.path.startswith('/index.html') or self.path.startswith('/?t='):
            if not role:
                self.send_response(200); self.send_header('Content-type', 'text/html; charset=utf-8'); self.send_header('Cache-Control', 'no-store, no-cache, must-revalidate, max-age=0'); self.end_headers(); self.wfile.write(LOGIN_HTML.encode('utf-8')); return
            self.send_response(200); self.send_header('Content-type', 'text/html; charset=utf-8'); self.send_header('Cache-Control', 'no-store, no-cache, must-revalidate, max-age=0'); self.end_headers(); self.wfile.write(HTML.encode('utf-8'))
