  if (isAdmin || localConfig.guest_can_see_secrets) { if(d.passwords) html += `<p style="color:red">كلمات المرور: ${d.passwords}</p>`; }
  if(d.notes) html += `<p>ملاحظات: ${d.notes}</p>`;
  document.getElementById('infoTitle').textContent = d.name; document.getElementById('infoBody').innerHTML = html;
  document.getElementById('infoEditBtn').style.display = canEdit ? 'block' : 'none'; document.getElementById('infoModal').classList.add('active');
