async function deleteCurrentEntity() { localData.entities = localData.entities.filter(e => e.id !== editingEntityId); localData.relations = localData.relations.filter(r => r.from !== editingEntityId && r.to !== editingEntityId); await saveData(); closeModal('entityModal'); }
function openAddRelation() {
  const nodes = cy.nodes(); if (nodes.length < 2) return;
  const f = document.getElementById('relFrom'), t = document.getElementById('relTo'); f.innerHTML = ''; t.innerHTML = '';
